(async () => {
  if (args?.[0]?.macroPass !== "postActiveEffects") return;

  const wf = workflow;
  if (!wf?.actor || wf.aborted || wf.activity?.type === "check") return;

  const targets = wf.targets?.documents ?? [];
  if (targets.length !== 1 || !targets[0]?.actor) {
    ui.notifications.warn("解除魔法需要选择一个生物目标。");
    return;
  }

  const target = targets[0].actor;
  const castLevel = Number(wf.castData?.castLevel ?? wf.spellLevel);
  const casterToken = wf.tokenDocument ?? wf.token?.document;
  const ability = wf.activity?.spellcastingAbility
    ?? wf.actor.spellcastingAbility;

  if (!Number.isFinite(castLevel)) return;

  const templateSuffix =
    ` ${game.i18n.localize("midi-qol.MeasuredTemplate")}`;

  const spells = new Map();

  for (const effect of target.effects) {
    if (
      effect.disabled ||
      effect.transfer ||
      effect.system?.type === "concentrating" ||
      effect.statuses?.has(CONFIG.specialStatusEffects.CONCENTRATING)
    ) continue;

    // Exclude Midi-QOL's template management effect.
    const templateItem = effect.getFlag("dnd5e", "item");

    if (
      effect.name?.endsWith(templateSuffix) &&
      templateItem?.uuid &&
      effect.origin === templateItem.uuid &&
      effect.getFlag("dae", "stackable") === "noneName" &&
      effect.getFlag("dae", "expiryMode") === "delete"
    ) continue;

    const manual = effect.getFlag("world", "dispelMagic");
    if (manual?.isSpell === false) continue;

    const cast = effect.getFlag("midi-qol", "castData");
    const origin = effect.system?.origin ?? {};

    let source = null;

    for (const uuid of [
      origin.activity,
      cast?.itemUuid,
      origin.item,
      effect.origin
    ]) {
      if (!uuid) continue;

      try {
        source = await fromUuid(uuid);
      } catch {
        source = null;
      }

      if (source) break;
    }

    const spellItem = source?.item
      ?? (source instanceof Item ? source : null);

    const concentrationItem = source?.getFlag?.(
      "dnd5e", "item"
    );

    const castFromSpell = cast?.itemUuid
      && Number.isFinite(Number(cast.baseLevel));

    if (
      manual?.isSpell !== true &&
      spellItem?.type !== "spell" &&
      concentrationItem?.type !== "spell" &&
      !castFromSpell
    ) continue;

    const level = Number(
      cast?.castLevel
      ?? manual?.level
      ?? effect.getFlag("dnd5e", "spellLevel")
      ?? spellItem?.system?.level
      ?? concentrationItem?.data?.system?.level
    );

    if (!Number.isFinite(level) || level < 0) continue;

    // Group effects belonging to the same casting.
    const key = origin.message
      ?? origin.effect
      ?? effect.getFlag("dnd5e", "dependentOn")
      ?? effect.uuid;

    if (!spells.has(key)) {
      spells.set(key, {
        name: spellItem?.name ?? effect.name,
        img: effect.img ?? spellItem?.img,
        level,
        ids: []
      });
    }

    const spell = spells.get(key);
    spell.ids.push(effect.id);
    spell.level = Math.max(spell.level, level);
  }

  if (!spells.size) return;

  const needsCheck = [...spells.values()]
    .some(spell => spell.level > castLevel);

  const checkActivity = needsCheck
    ? wf.item.system.activities.find(a =>
        a.type === "check" && a.name === "Dispel Check"
      )
    : null;

  if (
    needsCheck &&
    (
      !checkActivity ||
      !casterToken?.uuid ||
      !CONFIG.DND5E.abilities[ability]
    )
  ) {
    ui.notifications.error(
      "缺少 Dispel Check Activity、施法者 Token 或施法属性。"
    );
    return;
  }

  const results = [];

  for (const spell of spells.values()) {
    const dc = 10 + spell.level;

    let total;
    let success = spell.level <= castLevel;

    if (!success) {
      // Use a temporary Item so the Check Activity's
      // ability and DC survive Midi's internal cloning.
      const checkItem = wf.item.clone({}, { keepId: true });
      const check = checkItem.system.activities.get(checkActivity.id);

      check.updateSource({
        check: {
          ability,
          dc: {
            calculation: "",
            formula: String(dc)
          }
        }
      });

      check.prepareFinalData();

      const checkWf = await MidiQOL.completeActivityUse(
        check,
        {
          consume: false,
          midiOptions: {
            targetUuids: [casterToken.uuid],
            ignoreUserTargets: true,
            fastForward: true,
            workflowOptions: {
              targetConfirmation: "none",
              noProvokeReaction: true
            }
          }
        },
        { configure: false },
        { create: true }
      );

      const roll = checkWf?.saveRoll?.(casterToken)
        ?? checkWf?.tokenSaves?.[casterToken.uuid];

      if (
        checkWf?.aborted ||
        !Number.isFinite(roll?.total)
      ) {
        ui.notifications.warn("解除魔法检定未完成。");
        break;
      }

      total = roll.total;

      // Respect Midi's resolved check outcome.
      success = checkWf.saves?.has(casterToken)
        ?? (total >= dc);
    }

    if (success) {
      await MidiQOL.removeEffects({
        actorUuid: target.uuid,
        effects: spell.ids
      });
    }

    results.push({
      name: spell.name,
      img: spell.img,
      level: spell.level,
      success,
      total,
      dc
    });
  }

  if (!results.length) return;

  const escape = value =>
    foundry.utils.escapeHTML(String(value));

  const html = results.map(r => `
    <div style="
      display:flex;
      align-items:center;
      gap:8px;
      margin:4px 0;
    ">
      ${r.img ? `
        <img
          src="${escape(r.img)}"
          width="24"
          height="24"
          style="
            width:24px;
            height:24px;
            object-fit:cover;
            border:0;
            flex:none;
          "
        >
      ` : ""}
      <span>
        ${escape(r.name)}（${r.level}环）：
        ${r.success ? "解除成功" : "解除失败"}
        ${r.total === undefined
          ? ""
          : `（${r.total} / DC ${r.dc}）`}
      </span>
    </div>
  `).join("");

  await MidiQOL.addCardNote(wf, html, {
    anchor: "bottom",
    key: "dispel-magic.results"
  });
})();
